using System.Text.Json.Nodes;
using System.Text.RegularExpressions;
using Modeller.Core;
namespace Modeller.Application;

public sealed class RepositoryOperations(SnapshotRepository repository,RemoteDefinitions remote)
{
    private static string S(JsonObject o,string k,string fallback="")=>KnowledgeCorpus.Text(o,k,fallback);
    public static JsonObject Capabilities(string provider="filesystem")=>new(){["storage"]=true,["versioning"]=true,["history"]=true,["branching"]=provider=="git",["diff"]=provider=="git",["reviews"]=provider=="git"&&Environment.GetEnvironmentVariable("MODEL_REPOSITORY_PROVIDER") is "github" or "gitlab",["approvals"]=false,["locking"]=true,["webhooks"]=false,["ci"]=false,["releaseTags"]=false,["offline"]=provider=="filesystem"};
    public JsonObject Info()=>repository is GitRepository git?git.Info():new JsonObject{["provider"]=repository is SharePointRepository?"sharepoint":"filesystem",["capabilities"]=Capabilities(repository is SharePointRepository?"sharepoint":"filesystem")};
    public Task<JsonObject> Branch(JsonObject args,CancellationToken cancellation){cancellation.ThrowIfCancellationRequested();return Task.FromResult((repository as GitRepository??throw new ProcessingException("REPOSITORY_BRANCHING_NOT_SUPPORTED")).Branch(Data.Required(args,"branch"),Data.Required(args,"baseRevision")));}
    public Task<JsonObject> Diff(JsonObject args,CancellationToken cancellation){cancellation.ThrowIfCancellationRequested();return Task.FromResult((repository as GitRepository??throw new ProcessingException("REPOSITORY_DIFF_NOT_SUPPORTED")).Diff(Data.Required(args,"baseRevision"),Data.Required(args,"headRevision")));}
    private (string Root,string Path,bool Gitlab,Dictionary<string,string> Headers) Hosting(){
        var git=repository as GitRepository??throw new ProcessingException("REPOSITORY_HOSTING_NOT_SUPPORTED");var configured=Environment.GetEnvironmentVariable("MODEL_REPOSITORY_PROVIDER");if(configured is not("github" or "gitlab"))throw new ProcessingException("REPOSITORY_HOSTING_NOT_SUPPORTED");var gitlab=configured=="gitlab";var url=git.Remote;var match=Regex.Match(url,"^(?:https://|ssh://[^@]+@|[^@/:]+@)([^/:]+)(?::[0-9]+/|:|/)([A-Za-z0-9_./-]+?)(?:\\.git)?$");if(!match.Success)throw new ProcessingException("HOSTED_REPOSITORY_INVALID");var name=match.Groups[2].Value.TrimEnd('/');if(name.Contains("..",StringComparison.Ordinal)||name.Split('/').Length<2)throw new ProcessingException("HOSTED_REPOSITORY_INVALID");var host=match.Groups[1].Value;var root=Environment.GetEnvironmentVariable("MODEL_HOSTED_API_URL");if(string.IsNullOrEmpty(root))root=gitlab?"https://"+host+"/api/v4/":host=="github.com"?"https://api.github.com/":"https://"+host+"/api/v3/";var token=Environment.GetEnvironmentVariable("MODEL_HOSTED_TOKEN")??"";if(token.Length<1||token.Any(char.IsControl))throw new ProcessingException("HOSTED_CREDENTIAL_REQUIRED");var headers=new Dictionary<string,string>{[gitlab?"PRIVATE-TOKEN":"Authorization"]=gitlab?token:"Bearer "+token,["User-Agent"]="Clinical-Modeller"};return(root,gitlab?"projects/"+Uri.EscapeDataString(name):"repos/"+name,gitlab,headers);
    }
    public async Task<JsonObject> Branches(JsonObject args,CancellationToken cancellation){var(root,path,gitlab,headers)=Hosting();var page=KnowledgeCorpus.Number(args,"page",1);var reply=await remote.Send(root,path+(gitlab?"/repository/branches":"/branches")+"?per_page=100&page="+page,HttpMethod.Get,null,headers,cancellation);var rows=JsonNode.Parse(reply.Body) as JsonArray??throw new ProcessingException("HOSTED_RESPONSE_INVALID");var items=new JsonArray(rows.OfType<JsonObject>().Select(r=>(JsonNode)new JsonObject{["name"]=r["name"]?.DeepClone(),["revision"]=r["commit"]?[gitlab?"id":"sha"]?.DeepClone(),["protected"]=r["protected"]?.DeepClone()}).ToArray());return new JsonObject{["items"]=items,["page"]=page,["has_more_possible"]=items.Count==100};}
    public async Task<JsonObject> RequestReview(JsonObject args,CancellationToken cancellation){var(root,path,gitlab,headers)=Hosting();var branch=Data.Required(args,"branch");GitRepository.BranchName(branch);var target=Environment.GetEnvironmentVariable("MODEL_GIT_REVIEW_TARGET")??"main";GitRepository.BranchName(target);if(branch==target)throw new ProcessingException("HOSTED_REVIEW_BRANCH_REQUIRED");var title=Data.Required(args,"title");var body=S(args,"body");if(title.Length>200||body.Length>20000)throw new ProcessingException("HOSTED_REVIEW_INVALID");
        var lookup=await remote.Send(root,path+(gitlab?"/merge_requests?state=opened&source_branch="+Uri.EscapeDataString(branch)+"&target_branch="+Uri.EscapeDataString(target):"/pulls?state=open&head="+Uri.EscapeDataString(branch)+"&base="+Uri.EscapeDataString(target)),HttpMethod.Get,null,headers,cancellation);var existing=JsonNode.Parse(lookup.Body) as JsonArray??throw new ProcessingException("HOSTED_RESPONSE_INVALID");var match=existing.OfType<JsonObject>().FirstOrDefault();if(match is not null)return Review(match,gitlab);
        var document=gitlab?new JsonObject{["source_branch"]=branch,["target_branch"]=target,["title"]=title.StartsWith("Draft:",StringComparison.OrdinalIgnoreCase)?title:"Draft: "+title,["description"]=body,["remove_source_branch"]=false}:new JsonObject{["head"]=branch,["base"]=target,["title"]=title,["body"]=body,["draft"]=true};var response=await remote.Send(root,path+(gitlab?"/merge_requests":"/pulls"),HttpMethod.Post,document,headers,cancellation);return Review(JsonNode.Parse(response.Body) as JsonObject??throw new ProcessingException("HOSTED_RESPONSE_INVALID"),gitlab);
    }
    public async Task<JsonObject> GetReview(JsonObject args,CancellationToken cancellation){var(root,path,gitlab,headers)=Hosting();var number=args["number"]!.GetValue<int>();if(number<1)throw new ProcessingException("HOSTED_REVIEW_INVALID");var response=await remote.Send(root,path+(gitlab?"/merge_requests/":"/pulls/")+number,HttpMethod.Get,null,headers,cancellation);return Review(JsonNode.Parse(response.Body) as JsonObject??throw new ProcessingException("HOSTED_RESPONSE_INVALID"),gitlab);}
    private static JsonObject Review(JsonObject r,bool gitlab)=>new(){["number"]=r[gitlab?"iid":"number"]?.DeepClone(),["url"]=r[gitlab?"web_url":"html_url"]?.DeepClone(),["title"]=r["title"]?.DeepClone(),["state"]=r["state"]?.DeepClone(),["draft"]=r["draft"]?.DeepClone()??JsonValue.Create(S(r,"title").StartsWith("Draft:",StringComparison.OrdinalIgnoreCase)),["clinical_approval"]=false,["merged_by_modeller"]=false};
}
